/** Préstamos finitos: el calendario programa, sólo una liquidación real abona. */
@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class PrestamoProgramadoService {
 private final NamedParameterJdbcTemplate jdbc;
 private final EmpleadoService empleados;
 private final AlcanceDatosService alcance;
 private final MovimientoManualService movimientos;
 public record Plan(Long id,int numero,BigDecimal capital,BigDecimal interesAnterior,BigDecimal interesNuevo,BigDecimal porcentaje,String frecuencia,int cuotas,LocalDate inicio,LocalDate fin,boolean automatico,String motivo,String fecha,String usuario){}
 public record Registro(Long id,Long empleadoId,String empleado,String codigo,String concepto,BigDecimal principal,String moneda,String estado,Long version,UUID solicitud,BigDecimal capitalPendiente,BigDecimal interesPendiente,Plan plan,boolean programado){
  public String folio(){return "PRE-"+String.format(Locale.ROOT,"%06d",id);}public BigDecimal saldo(){return capitalPendiente.add(interesPendiente);}
 }
 public record CuotaVista(int numero,LocalDate fecha,BigDecimal capital,BigDecimal interes,boolean pagada){public BigDecimal total(){return capital.add(interes);}}
 public record Revision(BigDecimal capital,BigDecimal interesAnterior,BigDecimal interesNuevo,BigDecimal porcentaje,List<CalendarioCuotasPrestamo.Cuota> cuotas,String sello){public BigDecimal total(){return capital.add(interesAnterior).add(interesNuevo);}}
 public record Abono(Long nomina,String documento,BigDecimal capital,BigDecimal interes,String estado,String fecha){}
 public record ResumenEmpleado(long registros,long pendientes,BigDecimal saldo){}
 public boolean requiereReprogramar(Long id){var r=obtener(id);if(!r.programado()||r.estado().equals("BORRADOR")||r.estado().equals("CANCELADO"))return false;return jdbc.queryForObject("SELECT coalesce(sum(capital+interes),0) FROM prestamo_cuota_pendiente WHERE plan_id=:plan",p("PRESTAMO_LEER").addValue("plan",r.plan().id()),BigDecimal.class).compareTo(r.saldo())!=0;}
 public ResumenEmpleado resumenEmpleado(Long emp){empleado(emp);return jdbc.queryForObject("SELECT count(*) registros,count(*) FILTER(WHERE s.saldo>0) pendientes,coalesce(sum(s.saldo),0) saldo FROM prestamo_empleado p JOIN prestamo_saldo s ON s.id=p.id WHERE p.empleado_id=:emp AND p.institucion_id=:inst",p("PRESTAMO_LEER").addValue("emp",emp),(r,n)->new ResumenEmpleado(r.getLong("registros"),r.getLong("pendientes"),r.getBigDecimal("saldo")));}
 public record Fuente(Long id,String texto,BigDecimal saldo,String moneda){}
 public Map<String,Object> entregaRegistrada(Long id){obtener(id);return jdbc.queryForList("SELECT en.cuenta_codigo,en.cuenta_nombre,en.importe,en.referencia,en.motivo,en.movimiento_id,to_char(en.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username usuario FROM prestamo_entrega en JOIN institucion i ON i.id=en.institucion_id JOIN usuario u ON u.id=en.usuario_id WHERE en.prestamo_id=:id AND en.institucion_id=:inst",p("PRESTAMO_LEER").addValue("id",id)).stream().findFirst().orElse(null);}
 public String textoEmpleado(Long id){empleado(id);return jdbc.queryForObject("SELECT codigo||' · '||concat_ws(' ',nombres,primer_apellido,segundo_apellido) FROM empleado WHERE id=:emp AND institucion_id=:inst",p("PRESTAMO_LEER").addValue("emp",id),String.class);}
 public record Entrega(Fuente cuenta,BigDecimal importe,BigDecimal posterior,String sello){}
 private UsuarioPrincipal actor(String permiso){
  var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!(a.getPrincipal() instanceof UsuarioPrincipal p)||p.usuarioId()==null||p.institucionId()==null||p.accesoRecuperacion()||!p.alcanceInstitucional())throw denegado();
  boolean tiene=permiso.equals("PRESTAMO_LEER")?List.of("PRESTAMO_LEER","PRESTAMO_ADMINISTRAR").stream().anyMatch(empleados::permitido):empleados.permitido(permiso);
  if(!tiene||jdbc.queryForObject("SELECT count(*) FROM usuario WHERE id=:actor AND institucion_id=:inst AND estado='ACTIVO' AND tipo_cuenta='ADMINISTRATIVO'",new MapSqlParameterSource("actor",p.usuarioId()).addValue("inst",p.institucionId()),Long.class)!=1)throw denegado();return p;
 }
 public boolean permitido(String permiso){try{actor(permiso);return true;}catch(AccessDeniedException e){return false;}}
 private MapSqlParameterSource p(String permiso){var a=actor(permiso);return new MapSqlParameterSource("inst",a.institucionId()).addValue("actor",a.usuarioId());}
 public LocalDate hoy(){return jdbc.queryForObject("SELECT (CURRENT_TIMESTAMP AT TIME ZONE zona_horaria)::date FROM institucion WHERE id=:inst",p("PRESTAMO_LEER"),LocalDate.class);}
 private void empleado(Long id){if(id==null||jdbc.queryForObject("SELECT count(*) FROM empleado WHERE id=:emp AND institucion_id=:inst",p("PRESTAMO_LEER").addValue("emp",id),Long.class)!=1)throw denegado();}
 private void bloquear(Long emp){empleado(emp);jdbc.queryForObject("SELECT id FROM empleado WHERE id=:emp AND institucion_id=:inst FOR UPDATE",p("PRESTAMO_LEER").addValue("emp",emp),Long.class);}
 private static final String BASE=" FROM prestamo_empleado p JOIN empleado e ON e.id=p.empleado_id JOIN prestamo_saldo s ON s.id=p.id LEFT JOIN prestamo_entrega en ON en.prestamo_id=p.id LEFT JOIN LATERAL(SELECT * FROM prestamo_plan WHERE prestamo_id=p.id ORDER BY id DESC LIMIT 1) pl ON true ";
 private static final String COLUMNAS="SELECT p.*,concat_ws(' ',e.nombres,e.primer_apellido,e.segundo_apellido) empleado,e.codigo empleado_codigo,s.saldo,en.prestamo_id entregado,coalesce((SELECT sum(a.interes) FROM prestamo_cuota_abono a JOIN prestamo_plan ap ON ap.id=a.plan_id JOIN nomina_pago_intento ni ON ni.id=a.pago_id AND ni.estado='PAGADO' WHERE ap.prestamo_id=p.id),0)+coalesce((SELECT sum(a.interes) FROM prestamo_cuota_cero a JOIN prestamo_plan ap ON ap.id=a.plan_id WHERE ap.prestamo_id=p.id),0) interes_pagado,coalesce((SELECT sum(ap.interes_nuevo) FROM prestamo_plan ap WHERE ap.prestamo_id=p.id AND (ap.id=en.plan_id OR ap.clase='REESTRUCTURACION')),0) interes_pactado";
 private Registro map(java.sql.ResultSet r,int n)throws java.sql.SQLException{
  Long id=r.getLong("id");Plan pl=plan(id);BigDecimal interes=r.getObject("entregado")==null?BigDecimal.ZERO:r.getBigDecimal("interes_pactado").subtract(r.getBigDecimal("interes_pagado"));BigDecimal saldo=r.getBigDecimal("saldo"),cap=saldo.subtract(interes);String estado=r.getString("estado");if(estado.equals("ACTIVO")&&pl!=null&&saldo.signum()>0&&pl.fin().isBefore(hoy()))estado="VENCIDO";
  return new Registro(id,r.getLong("empleado_id"),r.getString("empleado"),r.getString("empleado_codigo"),r.getString("concepto_codigo")+" · "+r.getString("concepto_nombre"),r.getBigDecimal("importe"),r.getString("moneda"),estado,r.getLong("version"),r.getObject("solicitud",UUID.class),cap,interes,pl,r.getBoolean("programado"));
 }
 public Registro obtener(Long id){return jdbc.query(COLUMNAS+BASE+" WHERE p.id=:id AND p.institucion_id=:inst",p("PRESTAMO_LEER").addValue("id",id),this::map).stream().findFirst().orElseThrow(PrestamoProgramadoService::denegado);}
 public Plan plan(Long id){return jdbc.query("SELECT pl.*,to_char(pl.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username FROM prestamo_plan pl JOIN prestamo_empleado p ON p.id=pl.prestamo_id JOIN institucion i ON i.id=p.institucion_id JOIN usuario u ON u.id=pl.usuario_id WHERE pl.prestamo_id=:id AND p.institucion_id=:inst ORDER BY pl.id DESC LIMIT 1",p("PRESTAMO_LEER").addValue("id",id),(r,n)->new Plan(r.getLong("id"),r.getInt("numero"),r.getBigDecimal("capital"),r.getBigDecimal("interes_anterior"),r.getBigDecimal("interes_nuevo"),r.getBigDecimal("porcentaje"),r.getString("frecuencia"),r.getInt("cuotas"),r.getObject("inicio",LocalDate.class),r.getObject("fin",LocalDate.class),r.getBoolean("descontar_nomina"),r.getString("motivo"),r.getString("fecha"),r.getString("username"))).stream().findFirst().orElse(null);}
 public Page<Registro> listar(FiltroPrestamoPrograma original){var f=original.normalizado();var par=p("PRESTAMO_LEER");if(f.empleadoId()!=null)empleado(f.empleadoId());else if(!f.empleadoTexto().isBlank())throw regla("Selecciona un empleado de las sugerencias o limpia el campo.");
  String where=" WHERE p.institucion_id=:inst AND (:emp IS NULL OR p.empleado_id=:emp) AND strpos(lower(e.codigo||' '||concat_ws(' ',e.nombres,e.primer_apellido,e.segundo_apellido)||' PRE-'||lpad(p.id::text,6,'0')||' '||p.concepto_nombre),lower(:q))>0 AND (:estado='TODOS' OR :estado=CASE WHEN p.estado='ACTIVO' AND s.saldo>0 AND pl.fin<(CURRENT_TIMESTAMP AT TIME ZONE (SELECT zona_horaria FROM institucion WHERE id=:inst))::date THEN 'VENCIDO' ELSE p.estado END)";
  par.addValue("emp",f.empleadoId(),java.sql.Types.BIGINT).addValue("q",f.q()).addValue("estado",f.estado());var pg=PageRequest.of(f.pagina(),f.tamanio());long n=jdbc.queryForObject("SELECT count(*)"+BASE+where,par,Long.class);return new PageImpl<>(jdbc.query(COLUMNAS+BASE+where+" ORDER BY p.id DESC LIMIT :limite OFFSET :offset",par.addValue("limite",pg.getPageSize()).addValue("offset",pg.getOffset()),this::map),pg,n);
 }
 public List<OpcionAutocompletado> buscarEmpleados(String q){var par=p("PRESTAMO_LEER");String t=texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,concat_ws(' ',nombres,primer_apellido,segundo_apellido) nombre FROM empleado WHERE institucion_id=:inst AND strpos(lower(codigo||' '||concat_ws(' ',nombres,primer_apellido,segundo_apellido)),lower(:q))>0 ORDER BY nombres,id LIMIT 11",par.addValue("q",t),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),"Empleado de la institución"));}
 public List<OpcionAutocompletado> conceptos(String q){String t=texto(q,200);var par=p("PRESTAMO_LEER");if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre FROM concepto_nomina WHERE institucion_id=:inst AND activo AND naturaleza='DEDUCCION' AND aplicacion='CON_SALDO' AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY nombre,id LIMIT 11",par.addValue("q",t),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),"Deducción de préstamo · Con saldo"));}
 public Map<String,Object> concepto(Long id){return jdbc.queryForList("SELECT id,codigo,nombre,version FROM concepto_nomina WHERE id=:id AND institucion_id=:inst AND activo AND naturaleza='DEDUCCION' AND aplicacion='CON_SALDO'",p("PRESTAMO_LEER").addValue("id",id)).stream().findFirst().orElseThrow(()->regla("Selecciona una deducción activa de aplicación Con saldo."));}
 private Map<String,Object> conceptoOperacion(Long prestamo,boolean reprogramar,Long concepto){if(!reprogramar)return concepto(concepto);return jdbc.queryForList("SELECT concepto_id id,concepto_codigo codigo,concepto_nombre nombre,concepto_version version FROM prestamo_empleado WHERE id=:id AND institucion_id=:inst AND concepto_id=:concepto",p("PRESTAMO_LEER").addValue("id",prestamo).addValue("concepto",concepto)).stream().findFirst().orElseThrow(()->regla("La reprogramación conserva el concepto original del préstamo."));}
 private void elegible(Long emp,LocalDate inicio){empleado(emp);if(inicio==null||inicio.isBefore(hoy()))throw regla("El primer descuento debe ser hoy o una fecha futura.");if(jdbc.queryForObject("SELECT count(*) FROM empleado e JOIN empleado_laboral l ON l.empleado_id=e.id JOIN institucion i ON i.id=e.institucion_id WHERE e.id=:emp AND e.institucion_id=:inst AND i.activo AND e.activo AND l.situacion='ACTIVO' AND l.fecha_ingreso<=:inicio AND (l.fecha_baja IS NULL OR l.fecha_baja>=:inicio)",p("PRESTAMO_LEER").addValue("emp",emp).addValue("inicio",inicio),Long.class)!=1)throw regla("Confirma actividad laboral e ingreso compatibles con el primer descuento.");}
 private void reservas(Long id,Long emp){if(jdbc.queryForObject("SELECT count(*) FROM nomina_autorizacion a JOIN nomina_fila_efectiva ne ON ne.borrador_id=a.borrador_id AND ne.revision=a.revision WHERE ne.institucion_id=:inst AND ne.empleado_id=:emp AND ne.tratamiento<>'NO_APLICAR' AND ne.fuentes->'prestamos' @> jsonb_build_array(jsonb_build_object('id',cast(:id AS bigint))) AND NOT EXISTS(SELECT 1 FROM nomina_pago_intento ni WHERE ni.fila_id=ne.id AND ni.estado='PAGADO') AND NOT EXISTS(SELECT 1 FROM nomina_cierre_cero c WHERE c.fila_id=ne.id)",p("PRESTAMO_LEER").addValue("emp",emp).addValue("id",id),Long.class)>0)throw regla("El préstamo tiene cuotas comprometidas en una nómina confirmada pendiente de pago. Resuelve ese pago antes de reprogramar.");}
 public PrestamoProgramaForm formulario(Long id,boolean reprogramar){var r=obtener(id);if(!r.programado())throw regla("Este préstamo pertenece al proceso anterior; conserva su historial y condiciones.");if(reprogramar?!Set.of("ACTIVO","VENCIDO").contains(r.estado()):!r.estado().equals("BORRADOR"))throw regla("La operación no corresponde al estado actual del préstamo.");var f=new PrestamoProgramaForm();f.setEmpleadoId(r.empleadoId());f.setEmpleadoTexto(r.codigo()+" · "+r.empleado());var c=jdbc.queryForMap("SELECT concepto_id,concepto_version FROM prestamo_empleado WHERE id=:id",p("PRESTAMO_LEER").addValue("id",id));f.setConceptoId(((Number)c.get("concepto_id")).longValue());f.setConceptoVersion(((Number)c.get("concepto_version")).longValue());f.setConceptoTexto(r.concepto());f.setCapital(reprogramar?r.capitalPendiente():r.principal());f.setCuotas(reprogramar?2:r.plan().cuotas());f.setFrecuencia(r.plan().frecuencia());f.setInicio(hoy());f.setVersion(r.version());f.setSolicitud(r.solicitud());f.setPorcentaje(reprogramar?BigDecimal.ZERO:r.plan().porcentaje());f.setModalidad(f.getPorcentaje().signum()==0?"SIN_INTERES":"PORCENTAJE_TOTAL");f.setDescontarNomina(r.plan().automatico());return f;}
 public Revision revisar(Long id,boolean reprogramar,PrestamoProgramaForm f){p("PRESTAMO_ADMINISTRAR");elegible(f.getEmpleadoId(),f.getInicio());if(f.getCapital()==null||f.getCapital().signum()<0||f.getCapital().scale()>2||f.getCapital().precision()>17||f.getCuotas()==null||f.getPorcentaje()==null||f.getPorcentaje().signum()<0||f.getPorcentaje().compareTo(new BigDecimal("1000"))>0||f.getPorcentaje().scale()>4||f.getSolicitud()==null||f.getVersion()==null||f.getMotivo()==null||f.getMotivo().isBlank()||f.getMotivo().length()>2000)throw regla("Completa capital, porcentaje total, cuotas, fecha y motivo.");
  BigDecimal cap=f.getCapital(),interesPrevio=BigDecimal.ZERO;String actual="";
  if(id!=null){var r=obtener(id);if(!r.programado()||!r.empleadoId().equals(f.getEmpleadoId())||!r.version().equals(f.getVersion())||!r.solicitud().equals(f.getSolicitud()))throw regla("El préstamo cambió. Recarga antes de revisar.");actual=r.toString();if(reprogramar){if(!Set.of("ACTIVO","VENCIDO").contains(r.estado())||r.saldo().signum()<=0)throw regla("Sólo se reprograma un préstamo entregado con saldo pendiente.");reservas(id,r.empleadoId());cap=r.capitalPendiente();interesPrevio=r.interesPendiente();if(f.getCapital().compareTo(cap)!=0)throw regla("El capital pendiente cambió; vuelve a abrir la reprogramación.");}else if(!r.estado().equals("BORRADOR"))throw regla("Sólo se edita el borrador sin entregar.");}
  else if(reprogramar||cap.signum()<=0)throw regla("El importe del préstamo debe ser positivo.");
  f.setEmpleadoTexto(textoEmpleado(f.getEmpleadoId()));var c=conceptoOperacion(id,reprogramar,f.getConceptoId());f.setConceptoTexto(c.get("codigo")+" · "+c.get("nombre"));if(reprogramar&&jdbc.queryForObject("SELECT concepto_id FROM prestamo_empleado WHERE id=:id AND institucion_id=:inst",p("PRESTAMO_LEER").addValue("id",id),Long.class).longValue()!=f.getConceptoId())throw regla("La reprogramación conserva el concepto original del préstamo.");if(!Objects.equals(((Number)c.get("version")).longValue(),f.getConceptoVersion()))throw regla("El concepto cambió. Vuelve a seleccionarlo.");
  if(!Set.of("SIN_INTERES","PORCENTAJE_TOTAL").contains(f.getModalidad()))throw regla("Selecciona sin interés o porcentaje total del préstamo.");BigDecimal porcentaje=f.getModalidad().equals("SIN_INTERES")?BigDecimal.ZERO:f.getPorcentaje();BigDecimal nuevo=cap.multiply(porcentaje).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);f.setInteresNuevo(nuevo);
  var cuotas=CalendarioCuotasPrestamo.calcular(cap,interesPrevio.add(nuevo),f.getCuotas(),f.getInicio(),f.getFrecuencia());String sello=PreparacionNominaService.sello(actual+"|"+f.getEmpleadoId()+"|"+c+"|"+f.getSolicitud()+"|"+f.getVersion()+"|"+cap+"|"+interesPrevio+"|"+porcentaje+"|"+cuotas+"|"+f.isDescontarNomina()+"|"+f.getMotivo().strip());return new Revision(cap,interesPrevio,nuevo,porcentaje,cuotas,sello);
 }
@Transactional public Long guardar(Long id,boolean reprogramar,PrestamoProgramaForm f){p("PRESTAMO_ADMINISTRAR");bloquear(f.getEmpleadoId());if(id!=null)obtener(id);if(id!=null)jdbc.queryForObject("SELECT id FROM prestamo_empleado WHERE id=:id AND institucion_id=:inst FOR UPDATE",p("PRESTAMO_LEER").addValue("id",id),Long.class);var v=revisar(id,reprogramar,f);if(!Objects.equals(v.sello(),f.getSello()))throw regla("La captura o el saldo cambiaron. Revisa nuevamente; no se guardó nada.");var c=conceptoOperacion(id,reprogramar,f.getConceptoId());var par=p("PRESTAMO_LEER").addValue("emp",f.getEmpleadoId()).addValue("concepto",f.getConceptoId()).addValue("codigo",c.get("codigo")).addValue("nombre",c.get("nombre")).addValue("cv",f.getConceptoVersion()).addValue("capital",v.capital()).addValue("cuota",v.capital().min(v.cuotas().getFirst().total())).addValue("inicio",f.getInicio()).addValue("motivo",f.getMotivo().strip()).addValue("sol",f.getSolicitud());
  if(id==null){if(jdbc.queryForObject("SELECT count(*) FROM prestamo_empleado WHERE institucion_id=:inst AND solicitud=:sol",par,Long.class)>0)throw regla("Este formulario ya fue guardado. No se creó otro préstamo.");id=jdbc.queryForObject("INSERT INTO prestamo_empleado(institucion_id,empleado_id,concepto_id,concepto_codigo,concepto_nombre,concepto_version,moneda,importe,parcialidad,primer_descuento,solicitud,motivo,motivo_operacion,creado_por_id,actualizado_por_id,programado) SELECT :inst,:emp,:concepto,:codigo,:nombre,:cv,moneda_predeterminada,:capital,:cuota,:inicio,:sol,:motivo,:motivo,:actor,:actor,true FROM institucion WHERE id=:inst RETURNING id",par,Long.class);}
  else if(!reprogramar)jdbc.update("UPDATE prestamo_empleado SET concepto_id=:concepto,concepto_codigo=:codigo,concepto_nombre=:nombre,concepto_version=:cv,importe=:capital,parcialidad=:cuota,primer_descuento=:inicio,motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id",par.addValue("id",id));
  par.addValue("id",id).addValue("anterior",v.interesAnterior()).addValue("nuevo",v.interesNuevo()).addValue("porcentaje",v.porcentaje()).addValue("frecuencia",f.getFrecuencia()).addValue("n",f.getCuotas()).addValue("fin",v.cuotas().getLast().fecha()).addValue("automatico",f.isDescontarNomina()).addValue("clase",reprogramar?"REESTRUCTURACION":"ALTA");Long plan=jdbc.queryForObject("INSERT INTO prestamo_plan(prestamo_id,numero,clase,capital,interes_anterior,interes_nuevo,porcentaje,frecuencia,cuotas,inicio,fin,descontar_nomina,motivo,usuario_id) SELECT :id,coalesce(max(numero),0)+1,:clase,:capital,:anterior,:nuevo,:porcentaje,:frecuencia,:n,:inicio,:fin,:automatico,:motivo,:actor FROM prestamo_plan WHERE prestamo_id=:id RETURNING id",par,Long.class);
  for(var q:v.cuotas())jdbc.update("INSERT INTO prestamo_cuota(plan_id,numero,fecha,capital,interes) VALUES(:plan,:n,:fecha,:cap,:interes)",new MapSqlParameterSource("plan",plan).addValue("n",q.numero()).addValue("fecha",q.fecha()).addValue("cap",q.capital()).addValue("interes",q.interes()));if(reprogramar)estado(id,"Reprogramación: "+f.getMotivo().strip(),par);return id;
 }
 public List<CuotaVista> cuotas(Long id,Long planId){var r=obtener(id);Long elegido=planId==null?(r.plan()==null?null:r.plan().id()):planId;if(elegido==null)return List.of();return jdbc.query("SELECT c.*,NOT EXISTS(SELECT 1 FROM prestamo_cuota_pendiente cp WHERE cp.plan_id=c.plan_id AND cp.numero=c.numero) pagada FROM prestamo_cuota c JOIN prestamo_plan pl ON pl.id=c.plan_id WHERE pl.prestamo_id=:id AND c.plan_id=:plan ORDER BY c.numero",p("PRESTAMO_LEER").addValue("id",id).addValue("plan",elegido),(rs,n)->new CuotaVista(rs.getInt("numero"),rs.getObject("fecha",LocalDate.class),rs.getBigDecimal("capital"),rs.getBigDecimal("interes"),rs.getBoolean("pagada")));}
 public List<Map<String,Object>> historial(Long id){obtener(id);return jdbc.queryForList("SELECT pl.id,pl.numero,pl.clase,pl.frecuencia,pl.capital,pl.interes_anterior,pl.interes_nuevo,pl.motivo,to_char(pl.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username usuario FROM prestamo_plan pl JOIN prestamo_empleado p ON p.id=pl.prestamo_id JOIN institucion i ON i.id=p.institucion_id JOIN usuario u ON u.id=pl.usuario_id WHERE p.id=:id AND p.institucion_id=:inst ORDER BY pl.id DESC",p("PRESTAMO_LEER").addValue("id",id));}
public List<Abono> abonos(Long id){var registro=obtener(id);if(!registro.programado())return jdbc.query("SELECT ne.borrador_id,\'NPI-\'||ni.id,an.importe,0::numeric,CASE WHEN ni.estado=\'PAGADO\' THEN \'Abono vigente · proceso anterior\' ELSE \'Cancelado · saldo restaurado\' END,to_char(ni.ocurrido_en AT TIME ZONE i.zona_horaria,\'DD/MM/YYYY HH24:MI\') FROM prestamo_abono_nomina an JOIN nomina_pago_intento ni ON ni.id=an.pago_id JOIN nomina_borrador_empleado ne ON ne.id=ni.fila_id JOIN institucion i ON i.id=ni.institucion_id WHERE an.prestamo_id=:id AND ni.institucion_id=:inst ORDER BY ni.id DESC",p("PRESTAMO_LEER").addValue("id",id),(r,n)->new Abono(r.getLong(1),r.getString(2),r.getBigDecimal(3),r.getBigDecimal(4),r.getString(5),r.getString(6)));return jdbc.query("SELECT ne.borrador_id,'NPI-'||ni.id documento,sum(a.capital) capital,sum(a.interes) interes,CASE WHEN ni.estado='PAGADO' THEN 'Abono vigente' ELSE 'Cancelado · saldo restaurado' END estado,to_char(ni.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha FROM prestamo_cuota_abono a JOIN prestamo_plan pl ON pl.id=a.plan_id JOIN nomina_pago_intento ni ON ni.id=a.pago_id JOIN nomina_borrador_empleado ne ON ne.id=ni.fila_id JOIN institucion i ON i.id=ni.institucion_id WHERE pl.prestamo_id=:id AND ni.institucion_id=:inst GROUP BY ne.borrador_id,ni.id,i.zona_horaria UNION ALL SELECT nc.borrador_id,'Compensación sin tesorería',sum(a.capital),sum(a.interes),'Neto cero confirmado',to_char(nc.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') FROM prestamo_cuota_cero a JOIN prestamo_plan pl ON pl.id=a.plan_id JOIN nomina_cierre_cero nc ON nc.fila_id=a.fila_id JOIN institucion i ON i.id=nc.institucion_id WHERE pl.prestamo_id=:id AND nc.institucion_id=:inst GROUP BY nc.borrador_id,nc.ocurrido_en,i.zona_horaria",p("PRESTAMO_LEER").addValue("id",id),(r,n)->new Abono(r.getLong(1),r.getString(2),r.getBigDecimal(3),r.getBigDecimal(4),r.getString(5),r.getString(6)));}
 public List<Map<String,Object>> gestiones(Long id){obtener(id);return jdbc.queryForList("SELECT h.id,h.datos->'despues'->>'estado' estado,h.datos->'despues'->>'motivo_operacion' motivo,to_char(h.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username usuario FROM prestamo_empleado_historial h JOIN institucion i ON i.id=h.institucion_id JOIN usuario u ON u.id=h.usuario_id WHERE h.prestamo_id=:id AND h.institucion_id=:inst ORDER BY h.id DESC LIMIT 100",p("PRESTAMO_LEER").addValue("id",id));}
 private Fuente cuenta(Long id,String moneda){if(!empleados.permitido("CUENTA_FINANCIERA_LEER")&&!empleados.permitido("CUENTA_FINANCIERA_ADMINISTRAR"))throw denegado();alcance.validarRecurso(ModuloCatalogo.CUENTAS_FINANCIERAS,id);return jdbc.query("SELECT c.id,c.codigo||' · '||c.nombre texto,c.moneda,coalesce((SELECT saldo_posterior FROM movimiento_financiero WHERE cuenta_id=c.id ORDER BY secuencia_cuenta DESC LIMIT 1),c.saldo_inicial) saldo FROM cuenta_financiera c WHERE c.id=:id AND c.institucion_id=:inst AND c.activo AND c.tipo IN ('CAJA','BANCO') AND c.moneda=:moneda",p("PRESTAMO_ADMINISTRAR").addValue("id",id).addValue("moneda",moneda),(r,n)->new Fuente(r.getLong("id"),r.getString("texto"),r.getBigDecimal("saldo"),r.getString("moneda"))).stream().findFirst().orElseThrow(()->regla("Selecciona una cuenta activa compatible con el préstamo."));}
 public Entrega revisarEntrega(Long id,EntregarPrestamoForm f){p("PRESTAMO_ADMINISTRAR");if(!empleados.permitido("MOVIMIENTO_FINANCIERO_REGISTRAR"))throw denegado();var r=obtener(id);if(!r.programado()||!r.estado().equals("BORRADOR")||!r.version().equals(f.getVersion()))throw regla("El préstamo cambió o ya fue entregado/cancelado.");elegible(r.empleadoId(),r.plan().inicio());if(f.getReferencia()==null||f.getReferencia().isBlank()||f.getReferencia().length()>150||f.getMotivo()==null||f.getMotivo().isBlank()||f.getMotivo().length()>2000)throw regla("Captura referencia y motivo de entrega.");var c=cuenta(f.getCuentaId(),r.moneda());if(c.saldo().compareTo(r.principal())<0)throw regla(c.texto()+": disponible $"+c.saldo()+", solicitado $"+r.principal()+", faltan $"+r.principal().subtract(c.saldo())+". No se movió dinero.");if(jdbc.queryForObject("SELECT count(*) FROM motivo_financiero WHERE id=:mot AND institucion_id=:inst AND activo AND naturaleza IN ('EGRESO','AMBOS')",p("PRESTAMO_ADMINISTRAR").addValue("mot",f.getMotivoPagoId()),Long.class)!=1)throw regla("Selecciona un motivo financiero activo de egreso.");return new Entrega(c,r.principal(),c.saldo().subtract(r.principal()),PreparacionNominaService.sello(r+"|"+c+"|"+f.getMotivoPagoId()+"|"+f.getReferencia()+"|"+f.getMotivo()));}
@Transactional public void entregar(Long id,EntregarPrestamoForm f,String sello){p("PRESTAMO_ADMINISTRAR");if(!f.isEntregaConfirmada())throw regla("Confirma la entrega real antes de registrar el préstamo.");var r=obtener(id);bloquear(r.empleadoId());cuenta(f.getCuentaId(),r.moneda());jdbc.queryForObject("SELECT id FROM cuenta_financiera WHERE id=:id AND institucion_id=:inst FOR UPDATE",p("PRESTAMO_ADMINISTRAR").addValue("id",f.getCuentaId()),Long.class);var v=revisarEntrega(id,f);if(!v.sello().equals(sello))throw regla("La cuenta, el préstamo o la captura cambiaron. Revisa nuevamente; no se movió dinero.");var par=p("PRESTAMO_ADMINISTRAR");String zona=jdbc.queryForObject("SELECT zona_horaria FROM institucion WHERE id=:inst",par,String.class);var mov=movimientos.registrarPrestamo(new MovimientoManualRequest(actor("PRESTAMO_ADMINISTRAR").institucionId(),f.getCuentaId(),null,LocalDateTime.now(ZoneId.of(zona)).withSecond(0).withNano(0),DireccionMovimiento.EGRESO,f.getMotivoPagoId(),r.principal(),"Entrega préstamo "+r.folio(),r.folio(),"Personal de la institución","PRESTAMO:"+id));
  jdbc.update("INSERT INTO prestamo_entrega(prestamo_id,institucion_id,empleado_id,movimiento_id,cuenta_codigo,cuenta_nombre,referencia,importe,moneda,usuario_id,motivo,plan_id) SELECT p.id,p.institucion_id,p.empleado_id,:mov,c.codigo,c.nombre,:ref,p.importe,p.moneda,:actor,:motivo,:plan FROM prestamo_empleado p JOIN cuenta_financiera c ON c.id=:cuenta WHERE p.id=:id AND p.institucion_id=:inst",par.addValue("id",id).addValue("cuenta",f.getCuentaId()).addValue("mov",mov.id()).addValue("ref",f.getReferencia().strip()).addValue("motivo",f.getMotivo().strip()).addValue("plan",r.plan().id()));jdbc.update("UPDATE prestamo_empleado SET estado='ACTIVO',actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id",par);
 }
@Transactional public void cancelarBorrador(Long id,Long version,String motivo){p("PRESTAMO_ADMINISTRAR");var r=obtener(id);bloquear(r.empleadoId());r=obtener(id);if(!r.programado()||!r.estado().equals("BORRADOR")||!r.version().equals(version)||motivo==null||motivo.isBlank()||motivo.length()>2000)throw regla("Sólo se cancela el borrador vigente, con un motivo.");jdbc.update("UPDATE prestamo_empleado SET estado='CANCELADO',motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id",p("PRESTAMO_ADMINISTRAR").addValue("id",id).addValue("motivo",motivo.strip()));}
 public List<OpcionAutocompletado> cuentas(String q){p("PRESTAMO_ADMINISTRAR");if(!empleados.permitido("MOVIMIENTO_FINANCIERO_REGISTRAR")||(!empleados.permitido("CUENTA_FINANCIERA_LEER")&&!empleados.permitido("CUENTA_FINANCIERA_ADMINISTRAR")))throw denegado();String t=texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre,tipo FROM cuenta_financiera WHERE institucion_id=:inst AND activo AND tipo IN ('BANCO','CAJA') AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY codigo LIMIT 11",p("PRESTAMO_ADMINISTRAR").addValue("q",t),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),r.getString("tipo")));}
 public List<OpcionAutocompletado> motivos(String q){p("PRESTAMO_ADMINISTRAR");String t=texto(q,200);if(!t.isBlank()&&t.length()<3)return List.of();return jdbc.query("SELECT id,codigo,nombre FROM motivo_financiero WHERE institucion_id=:inst AND activo AND naturaleza IN ('EGRESO','AMBOS') AND strpos(lower(codigo||' '||nombre),lower(:q))>0 ORDER BY codigo LIMIT 11",p("PRESTAMO_ADMINISTRAR").addValue("q",t),(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),"Egreso"));}
 private void estado(Long id,String motivo,MapSqlParameterSource par){jdbc.update("UPDATE prestamo_empleado SET estado=CASE WHEN (SELECT saldo FROM prestamo_saldo WHERE id=:id)=0 THEN 'LIQUIDADO' ELSE 'ACTIVO' END,motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:inst",par.addValue("id",id).addValue("motivo",motivo));}
 private static String texto(String q,int max){return q==null?"":q.strip().substring(0,Math.min(q.strip().length(),max));}
 private static AccessDeniedException denegado(){return new AccessDeniedException("Se requiere permiso de préstamos y acceso administrativo institucional.");}
 private static ReglaNegocioException regla(String s){return new ReglaNegocioException(s);}
}
